    if(button.matches('[data-ely-mail-remove-file]')){button.closest('[data-ely-mail-file]').remove();changed(root,'attachment',button.value,{removed:true});emit(root,'remove-attachment',{value:button.value});}
    if(button.matches('[data-ely-mail-discard]')){composer.querySelectorAll('input:not([type=hidden]),textarea').forEach(field=>field.value='');composer.querySelectorAll('[data-ely-mail-file]').forEach(file=>file.remove());composer.querySelector('[data-ely-mail-copy-fields]').hidden=true;composer.querySelector('[data-ely-mail-copies]').setAttribute('aria-expanded','false');updateDraft();composer.querySelector('[data-ely-status]').textContent='Discarded.';changed(root,'draft','');}
