    if(button.matches('[data-ely-mail-custom]')){closeMenu(owner);owner.querySelector('dialog').showModal();owner.querySelector('[data-ely-mail-when]').focus();}
    if(button.matches('[data-ely-mail-time-cancel]')){owner.querySelector('dialog').close();(composer?.querySelector('[data-ely-mail-compose-schedule]')||owner.querySelector('[data-ely-mail-time-menu]')).focus();}
    if(button.matches('[data-ely-mail-preset]'))requestTime(owner,button.value);
