    if(form.matches('[data-ely-mail-compose]')){if(!updateDraft()||!form.reportValidity()){event.preventDefault();event.stopImmediatePropagation();return;}form.querySelector('[data-ely-status]').textContent='Send requested.';}
    if(form.matches('[data-ely-mail-time-form]')){const owner=form.closest('[data-ely-mail-time]'),field=form.querySelector('[data-ely-mail-when]');if(!requestTime(owner,field.value,form)){event.preventDefault();event.stopImmediatePropagation();field.setCustomValidity('Choose a time in the future.');field.reportValidity();return;}if(composer){event.preventDefault();event.stopImmediatePropagation();const data=new FormData(composer);for(const [key,value] of new FormData(form))if(key!=='value')data.set(key,value);emit(root,'schedule-send',{formData:data,values:[...data]});}}
