    for(const [label,offline] of [['Online',false],['Offline',true]]){const group=rows.filter(row=>(row.dataset.presence==='offline')===offline);if(!group.length)continue;const heading=document.createElement('h3');heading.textContent=label+' '+group.length;list.append(heading,...group);}
